MATCH (u:User)-->(g:Group)-->(p:Parcel)
 WHERE u.uuuid = ${ bearer.uuid }
 AND g.uuid = ${ uuid } AND p.uuid = ${ parcel_id }
 WITH u, g, p
 OPTIONAL MATCH (g)<--(a:Assign)
 WITH DISTINCT u, g, p, a
 MATCH (tenant:User)-[rel:IS_TENANT]->(p)
 WHERE tenant.uuid = ${ tenant_id }
 AND ( (u)-->(a)-->(p) OR (u)-[:IS_OWNER]->(g) )
 RETURN DISTINCT rel AS is_in, tenant AS the_tenant, p AS parcel
